// 提取 LINE 訊息資訊
const lineEvent = $input.first().json.body.events[0];
const userMessage = lineEvent.message.text;
const userId = lineEvent.source.userId;
const replyToken = lineEvent.replyToken;
// 記錄開始處理的時間戳記 (毫秒)
const startTime = Date.now()

// 格式化為 AI Agent 需要的格式
return {
	chatInput: userMessage,
	sessionId: userId,
	replyToken: replyToken,
	timestamp: new Date().toISOString(),
    startTime: startTime
};

// 取得 AI 的輸出結果或錯誤資訊
const inputData = $input.first().json;
const replyToken = $('格式化訊息資料1').first().json.replyToken;
const startTime = $('格式化訊息資料1').first().json.startTime; 

// --- 0. 計算延遲 ---
const endTime = Date.now();
const latencyMs = startTime ? (endTime - startTime) : 0;

// ✨ 1. 攔截錯誤並設計「雙軌訊息」
let aiResponse = "";
let lineMessage = ""; // 新增：專門給 LINE 使用者的友善訊息
let isError = false;

if (inputData.error) {
    // 發生 503 等 API 崩潰時
    aiResponse = "API 呼叫失敗: " + inputData.error.message; // 👉 寫入 Google Sheets 的真實錯誤
    lineMessage = "👨‍⚕️ 系統目前查閱資料較為繁忙，請您稍後再試一次！"; // 👉 傳給使用者的安撫訊息
    isError = true;
} else {
    // 正常運作時
    aiResponse = inputData.output || "";
    lineMessage = aiResponse; // 正常時兩者相同
}

// --- 2. 判定使用的工具 ---
let toolUsed = "None"; 
if (inputData.intermediateSteps && inputData.intermediateSteps.length > 0) {
  const allTools = inputData.intermediateSteps.map(step => step.action.tool);
  const uniqueTools = [...new Set(allTools)];
  toolUsed = uniqueTools.join(", ");
}

// --- 3. 提取警示層級 ---
let warningLevel = "🔵 注意 (Caution)"; 
if (isError) {
    warningLevel = "⚫ 系統錯誤 (503 Error)"; 
} else if (aiResponse.includes("🔴")) {
    warningLevel = "🔴 危險 (High Risk)";
} else if (aiResponse.includes("🟡")) {
    warningLevel = "🟡 警告 (Warning)";
} else if (aiResponse.includes("🔵")) {
    warningLevel = "🔵 注意 (Caution)";
}

// --- 4. 提取模型版本 ---
const modelVersion = "Gemini 3 Flash preview (Full Hybrid)"; 

// --- 5. 清理回應文字 ---
let responseText = aiResponse.replace(/\\n/g, '\n').replace(/"/g, "'");
let finalLineMessage = lineMessage.replace(/\\n/g, '\n').replace(/"/g, "'");

// 回傳結果
return {
  replyToken: replyToken,
  responseText: responseText,     // 👈 記錄真實錯誤
  lineMessage: finalLineMessage, // 👈 新增欄位，供 LINE 節點傳送友善訊息
  toolUsed: toolUsed, 
  warningLevel: warningLevel, 
  modelVersion: modelVersion, 
  timestamp: new Date().toISOString(),
  latencyMs: latencyMs 
};

