// 提取 LINE 訊息資訊
const lineEvent = $input.first().json.body.events[0];
const userMessage = lineEvent.message.text.trim(); // 加入 trim()
const userId = lineEvent.source.userId;
const replyToken = lineEvent.replyToken;

// 改善正規表達式，允許更靈活的空白符號
const regex = /^姓名：\s*(.+?)\s+身高：\s*(.+?)\s+體重：\s*(.+?)\s+年齡：\s*(.+?)\s*$/;
const matches = userMessage.match(regex);

if (matches) {
  const name = matches[1].trim();
  const height = matches[2].trim();
  const weight = matches[3].trim();
  const age = matches[4].trim();
  
  // 驗證資料不為空
  if (name && height && weight && age) {
    return {
      userId: userId,
      name: name,
      height: height,
      weight: weight,
      age: age,
      timestamp: new Date().toISOString(),
      replyToken: replyToken,
      dataType: 'profile',
      isValid: true
    };
  } else {
    return {
      userId: userId,
      replyToken: replyToken,
      isValid: false,
      error: '資料格式正確但內容不完整'
    };
  }
} else {
  return {
    userId: userId,
    replyToken: replyToken,
    isValid: false,
    error: '資料格式不正確'
  };
}

// 擷取原始的 LINE Webhook 資料
const lineEvent = $input.first().json.body.events[0];
const userMessage = lineEvent.message.text.trim(); // 加入 trim()
const userId = lineEvent.source.userId;
const replyToken = lineEvent.replyToken;

// 改善正規表達式
const regex = /^評價：\s*([1-5])\s*星\s*$/;
const matches = userMessage.match(regex);

if (matches) {
  const rating = matches[1].trim();
  
  return {
    userId: userId,
    rating: rating,
    timestamp: new Date().toISOString(),
    replyToken: replyToken,
    dataType: 'rating',
    isValid: true
  };
} else {
  return {
    userId: userId,
    replyToken: replyToken,
    isValid: false,
    error: '評價格式不正確'
  };
}

