// 接收 Google Sheets 的執行結果
const inputData = $input.first().json;

// 我們需要還原一些原始資料 (dataType, replyToken)，
// 因為 Google Sheets 節點只會回傳寫入的欄位。
// 這些資料存在於前一個節點 (解析使用者資料1 或 解析使用者評價1) 的輸入中。

let originalData = {};
let dataType = '';

try {
  // 嘗試從「解析使用者資料1」獲取 context (如果是個人資料路徑)
  const profileNode = $('解析使用者資料1');
  if (profileNode && profileNode.first()) {
    originalData = profileNode.first().json;
    dataType = 'profile';
  }
} catch(e) {}

if (!dataType) {
  try {
    // 嘗試從「解析使用者評價1」獲取 context (如果是評價路徑)
    const ratingNode = $('解析使用者評價1');
    if (ratingNode && ratingNode.first()) {
       originalData = ratingNode.first().json;
       dataType = 'rating';
    }
  } catch(e) {}
}

// 確保我們有 replyToken
const replyToken = originalData.replyToken || '';

return {
  success: true,
  currentData: {
    ...inputData, // 包含 userId, name, etc.
    dataType: dataType, 
    replyToken: replyToken
  }
};
